mapper.select:
SELECT PRODUCT_ID, PRODUCT_NAME, CATEGORY, FN_FORMAT_AMOUNT(UNIT_PRICE) AS UNIT_PRICE, REGEXP_REPLACE(DESCRIPTION, '\s+', ' ') AS DESCRIPTION_CLEAN FROM PRODUCTS WHERE IS_ACTIVE = 1
AND (REGEXP_LIKE(PRODUCT_NAME, #{keyword}, 'i') OR REGEXP_LIKE(NVL(DESCRIPTION, ''), #{keyword}, 'i'))
AND CATEGORY = #{category}
AND UNIT_PRICE >= #{minPrice}
AND UNIT_PRICE <= #{maxPrice}
ORDER BY
UNIT_PRICE ASC UNIT_PRICE DESC PRODUCT_NAME ASC PRODUCT_ID DESC
